final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  var window: UIWindow?

  // Cold launch only — the process was not alive before this
  func scene(_ scene: UIScene, willConnectTo session: UISceneSession,
             options: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene else { return }
    window = UIWindow(windowScene: windowScene)
    window?.rootViewController = RootViewController()
    window?.makeKeyAndVisible()
  }

  // Cold launch AND every resume from the switcher — the honest session signal
  func sceneWillEnterForeground(_ scene: UIScene) {
    Session.shared.foregroundEntered()
  }

  // Also fires after Face ID, Control Center, an incoming call — NOT a session
  func sceneDidBecomeActive(_ scene: UIScene) {
    resumeTimers()
  }

  func sceneDidEnterBackground(_ scene: UIScene) {
    Session.shared.leftForeground()
    saveDraft()
  }
}

final class Session {
  static let shared = Session()
  private var lastLeft: Date?

  func foregroundEntered() {
    // A launch into the background for a push or a BGTask must not count
    guard UIApplication.shared.applicationState != .background else { return }
    let gap = lastLeft.map { Date().timeIntervalSince($0) } ?? .infinity
    if gap > 30 { Analytics.log("session_start") }   // idle gap, not every activation
  }

  func leftForeground() { lastLeft = Date() }
}

final class SceneDelegate: UIResponder, UIWindowSceneDelegate {

