// RIGHT: one owner, ended exactly once, with a real expiration path
final class BackgroundTask {
  private var id: UIBackgroundTaskIdentifier = .invalid

  func begin(_ name: String) -> Bool {
    id = UIApplication.shared.beginBackgroundTask(withName: name) { [weak self] in
      self?.end()          // last chance, on the main thread, synchronous
    }
    return id != .invalid  // the system can refuse
  }

  func end() {
    guard id != .invalid else { return }   // ending twice is a crash
    UIApplication.shared.endBackgroundTask(id)
    id = .invalid
  }
}

func flushOnBackground() async {
  let task = BackgroundTask()
  guard task.begin("flush") else { return }
  defer { task.end() }

  print(UIApplication.shared.backgroundTimeRemaining)   // measure, do not assume
  try? await analytics.flush()
}

// 1. Register BEFORE didFinishLaunching returns, once per identifier
func application(_ app: UIApplication,
                 didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
  BGTaskScheduler.shared.register(
    forTaskWithIdentifier: "com.example.app.nightly-sync",
    using: nil                                   // nil = a system-provided queue
  ) { task in
    handleSync(task as! BGProcessingTask)
  }
  scheduleSync()
  return true
}

// 2. earliestBeginDate is a floor, not an appointment
func scheduleSync() {
  let request = BGProcessingTaskRequest(identifier: "com.example.app.nightly-sync")
  request.requiresExternalPower = true
  request.requiresNetworkConnectivity = true
  request.earliestBeginDate = Date(timeIntervalSinceNow: 6 * 3600)
  do {
    try BGTaskScheduler.shared.submit(request)
  } catch {
    logger.error("submit failed: \(error)")      // never swallow this with try?
  }
}

// 3. Re-arm first, finish always
func handleSync(_ task: BGProcessingTask) {
  scheduleSync()                                 // or this run is the last one ever

  let work = Task {
    do { try await syncEngine.run(); task.setTaskCompleted(success: true) }
    catch { task.setTaskCompleted(success: false) }
  }

  task.expirationHandler = {
    work.cancel()
    task.setTaskCompleted(success: false)        // silence here = killed and throttled
  }
}

import BackgroundTasks
import os

private let logger = Logger(subsystem: "com.example.app", category: "bgtask")

func handleSync(_ task: BGProcessingTask) {
  // Leave evidence a real overnight run happened — Console can be filtered on this
  logger.notice("bg run started: \(task.identifier, privacy: .public)")

  let work = Task {
    try await syncEngine.run()
    logger.notice("nightly-sync finished")
    task.setTaskCompleted(success: true)
  }
  task.expirationHandler = {
    logger.error("nightly-sync expired")
    work.cancel()
    task.setTaskCompleted(success: false)
  }
}

