// The payload and headers the server must send:
//
//   :path          /3/device/<token>
//   apns-push-type background      <- required; alert here means no background wake
//   apns-priority  5               <- 10 is rejected with BadPriority
//   apns-topic     com.example.app
//   apns-collapse-id feed-v1       <- coalesce a burst into one wake
//   apns-expiration 0              <- "now or never"; use a deadline if it matters
//
//   { "aps": { "content-available": 1 }, "reason": "feed" }
//
// WRONG — mixing the two: this is delivered as a normal alert, not a wake
//   { "aps": { "content-available": 1, "alert": { "body": "New posts" } } }

func application(_ app: UIApplication,
                 didReceiveRemoteNotification payload: [AnyHashable: Any],
                 fetchCompletionHandler completion: @escaping (UIBackgroundFetchResult) -> Void) {

  // ~30 seconds, and the answer must be truthful: always reporting .noData
  // is how you teach the system to stop waking you.
  Task {
    do {
      let changed = try await syncEngine.pullChanges()
      completion(changed ? .newData : .noData)
    } catch {
      completion(.failed)
    }
  }
}

// The push is a hint. The foreground path is the mechanism.
func sceneWillEnterForeground(_ scene: UIScene) {
  Task { try? await syncEngine.pullChanges() }
}

import UserNotifications

final class NotificationService: UNNotificationServiceExtension {
  private var handler: ((UNNotificationContent) -> Void)?
  private var bestAttempt: UNMutableNotificationContent?

  override func didReceive(
    _ request: UNNotificationRequest,
    withContentHandler contentHandler: @escaping (UNNotificationContent) -> Void
  ) {
    self.handler = contentHandler
    // Keep a shippable copy from the first line: expiry can come at any moment.
    guard let content = request.content.mutableCopy() as? UNMutableNotificationContent else {
      return contentHandler(request.content)
    }
    bestAttempt = content

    // The payload arrives encrypted; only this process can turn it into words.
    if let sealed = content.userInfo["ciphertext"] as? String,
       let plain = try? Crypto.open(sealed) {
      content.title = plain.title
      content.body = plain.body
      content.threadIdentifier = plain.chatID   // groups the thread in Notification Center
    }

    // Media is a bonus, never a blocker — deliver text even if the download fails.
    guard let url = URL(string: content.userInfo["avatar"] as? String ?? "") else {
      return contentHandler(content)
    }
    let config = URLSessionConfiguration.ephemeral
    config.timeoutIntervalForRequest = 8   // well under the ~30 s the extension gets
    URLSession(configuration: config).downloadTask(with: url) { file, _, _ in
      if let file, let attachment = try? UNNotificationAttachment(identifier: "avatar", url: file) {
        content.attachments = [attachment]
      }
      contentHandler(content)
    }.resume()
  }

  override func serviceExtensionTimeWillExpire() {
    // Never let the raw payload through: ship what we have.
    if let bestAttempt { handler?(bestAttempt) }
  }
}

// 1. Register categories once, at launch — before any notification can arrive.
func application(
  _ app: UIApplication,
  didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?
) -> Bool {
  let reply = UNTextInputNotificationAction(
    identifier: "REPLY",
    title: "Reply",
    options: [],                       // no .foreground: handled in the background
    textInputButtonTitle: "Send",
    textInputPlaceholder: "Message")
  let mute = UNNotificationAction(identifier: "MUTE", title: "Mute", options: [.destructive])
  let category = UNNotificationCategory(
    identifier: "MESSAGE",             // matches "category":"MESSAGE" in the aps payload
    actions: [reply, mute],
    intentIdentifiers: [],
    options: [.customDismissAction])   // without this, dismissals are never reported

  let center = UNUserNotificationCenter.current()
  center.setNotificationCategories([category])
  center.delegate = self               // must be set before this method returns
  return true
}

extension AppDelegate: UNUserNotificationCenterDelegate {
  // Frontmost only. Returning [] hides the banner.
  func userNotificationCenter(
    _ center: UNUserNotificationCenter,
    willPresent notification: UNNotification
  ) async -> UNNotificationPresentationOptions {
    let chatID = notification.request.content.threadIdentifier
    guard chatID != router.visibleChatID else { return [] }   // already on screen
    return [.banner, .list, .sound]                           // .alert is gone since iOS 14
  }

  // Every tap and every action, foreground or not — this is where routing lives.
  func userNotificationCenter(
    _ center: UNUserNotificationCenter,
    didReceive response: UNNotificationResponse
  ) async {
    let chatID = response.notification.request.content.threadIdentifier
    switch response.actionIdentifier {
    case "REPLY":
      let text = (response as? UNTextInputNotificationResponse)?.userText ?? ""
      await api.send(text, to: chatID)
    case "MUTE":
      await api.mute(chatID)
    case UNNotificationDefaultActionIdentifier:
      router.open(.chat(chatID))
    default:
      break
    }
  }
}

