// "Nothing is delivered" is usually a settings question, not an APNs question.
func diagnose() async -> String {
  let settings = await center.notificationSettings()
  switch settings.authorizationStatus {
  case .notDetermined: return "never asked"
  case .denied:        return "denied — only Settings can undo this"
  case .provisional:   return "quiet delivery: Notification Center only, no banner or sound"
  case .authorized, .ephemeral:
    // Authorised still says nothing about what the user actually sees.
    var off: [String] = []
    if settings.alertSetting != .enabled { off.append("banners") }
    if settings.soundSetting != .enabled { off.append("sound") }
    if settings.lockScreenSetting != .enabled { off.append("lock screen") }
    if settings.scheduledDeliverySetting == .enabled { off.append("batched by Scheduled Summary") }
    return off.isEmpty ? "fully visible" : "authorised but muted: " + off.joined(separator: ", ")
  @unknown default: return "unknown"
  }
}

