final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  // Warm path: the app is already running.
  func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
    handle(userActivity)
  }

  // Cold path: easy to forget, and it is the one testers hit.
  func scene(_ scene: UIScene,
             willConnectTo session: UISceneSession,
             options: UIScene.ConnectionOptions) {
    options.userActivities.forEach(handle)
  }

  private func handle(_ activity: NSUserActivity) {
    guard activity.activityType == NSUserActivityTypeBrowsingWeb,
          let url = activity.webpageURL,
          url.host == "example.com" else { return }   // the URL is untrusted input
    router.open(Route(url) ?? .home)                  // unknown path -> somewhere sane
  }
}

