// UIKit: one activity per scene, carrying ids only.
final class SceneDelegate: UIResponder, UIWindowSceneDelegate {
  private let router = Router()

  func scene(_ scene: UIScene,
             willConnectTo session: UISceneSession,
             options: UIScene.ConnectionOptions) {
    // A relaunched window arrives with whatever we handed over at disconnect.
    if let activity = session.stateRestorationActivity,
       let id = activity.userInfo?["postID"] as? String {
      router.path = [.post(id)]            // rebuilt from an id, not from a graph of objects
    }
    // ...build the window from router.path
  }

  // Called once, when the scene disconnects — not on every navigation.
  func stateRestorationActivity(for scene: UIScene) -> NSUserActivity? {
    guard case .post(let id)? = router.path.last else { return nil }
    let activity = NSUserActivity(activityType: "com.example.app.post")
    activity.userInfo = ["postID": id]     // plist types, a few KB at most
    activity.targetContentIdentifier = id  // lets the system dedupe windows
    return activity
  }
}

