// RIGHT: know whether this launch was prewarmed, and start the clock at the real launch.
let wasPrewarmed = ProcessInfo.processInfo.environment["ActivePrewarm"] == "1"

private let signposter = OSSignposter(subsystem: "com.example.app", category: "launch")
private var launchInterval: OSSignpostIntervalState?

func application(
  _ app: UIApplication,
  didFinishLaunchingWithOptions options: [UIApplication.LaunchOptionsKey: Any]?
) -> Bool {
  // This method does NOT run during prewarm: it is the first honest timestamp.
  launchInterval = signposter.beginInterval("time to first frame")
  Analytics.shared.startSession(prewarmed: wasPrewarmed)   // session begins here, not in init
  return true
}

extension RootViewController {
  override func viewDidAppear(_ animated: Bool) {
    super.viewDidAppear(animated)
    // The frame is only really on screen once this transaction has committed.
    CATransaction.setCompletionBlock {
      guard let state = launchInterval else { return }
      signposter.endInterval("time to first frame", state)
      launchInterval = nil
      // Tag the sample so prewarmed launches never pollute the p90.
      Metrics.record(.timeToFirstFrame, prewarmed: wasPrewarmed)
    }
  }
}

