func application(
  _ app: UIApplication,
  didReceiveRemoteNotification info: [AnyHashable: Any]
) async -> UIBackgroundFetchResult {
  // Before first unlock, files and Keychain items simply are not readable.
  guard app.isProtectedDataAvailable else { return .noData }   // .failed would be a lie

  // ~30 seconds. Not calling back at all gets future wake-ups throttled.
  do {
    let changed = try await withThrowingTaskGroup(of: Bool.self) { group in
      group.addTask { try await Sync.pullChanges() }
      group.addTask { try await Task.sleep(for: .seconds(20)); throw TimeoutError() }
      let result = try await group.next()!
      group.cancelAll()
      return result
    }
    return changed ? .newData : .noData
  } catch {
    return .failed
  }
}

