// Location is the exception: these relaunch the app even after a force-quit or a reboot.
final class TripTracker: NSObject, CLLocationManagerDelegate {
  private let manager = CLLocationManager()

  func start() {
    manager.delegate = self
    manager.allowsBackgroundLocationUpdates = true
    manager.startMonitoringSignificantLocationChanges()   // survives force-quit
    // manager.startUpdatingLocation()                    // does NOT: standard updates stop
  }

  func locationManager(_ m: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
    // May arrive in a process the system relaunched into the background with no window.
    Sync.enqueue(locations)
  }
}

// PushKit also relaunches a force-quit app — but only on this contract.
extension CallService: PKPushRegistryDelegate {
  func pushRegistry(_ registry: PKPushRegistry,
                    didReceiveIncomingPushWith payload: PKPushPayload,
                    for type: PKPushType) async {
    // Since iOS 13 you MUST report a call for every VoIP push, synchronously here.
    // Skip it and iOS kills the app and stops delivering VoIP pushes to you.
    let update = CXCallUpdate()
    update.remoteHandle = CXHandle(type: .phoneNumber, value: payload.dictionaryPayload["from"] as? String ?? "")
    try? await provider.reportNewIncomingCall(with: UUID(), update: update)
  }
}

// Because silent push may never arrive, reconcile on every foreground as well.
func sceneWillEnterForeground(_ scene: UIScene) {
  Task { await Sync.reconcile() }   // the only refresh path you fully control
}
